from pathlib import Path
import json, html, os, re
from urllib.parse import urlsplit
root=Path(__file__).parent; dist=root/'docs'; data=json.loads((root/'content/site.json').read_text(encoding='utf-8')); photos=json.loads((root/'content/photos.json').read_text(encoding='utf-8')); pm={p['id']:p for p in photos}
# Optional full public URL, including the repository name for a project site.
origin = os.environ.get('SITE_URL', data.get('siteUrl', '')).strip().rstrip('/')
if origin:
 parsed_origin = urlsplit(origin)
 if parsed_origin.scheme not in ('http', 'https') or not parsed_origin.netloc or parsed_origin.query or parsed_origin.fragment:
  raise ValueError('siteUrl must be a full http(s) URL without a query or fragment.')

def relative_urls(markup, rel):
 # Relative references work on both username.github.io/repository/ and custom domains.
 prefix = '../' * len(rel.split('/')) if rel else './'
 markup = re.sub(r'(href|src)="/(?!/)([^"]*)"', lambda m: m[1] + '="' + prefix + m[2] + '"', markup)
 markup = re.sub(r'srcset="([^"]*)"', lambda m: 'srcset="' + m[1].replace('/assets/', prefix + 'assets/') + '"', markup)
 if not origin:
  markup = re.sub(r'<link rel="canonical"[^>]*>|<meta property="og:(?:url|image)"[^>]*>', '', markup)
 return markup

WA=data['whatsapp']; E=html.escape
arrow='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>'
star='<svg class="spark" viewBox="0 0 80 80" aria-hidden="true"><path d="M40 0l7 25L68 12 55 33l25 7-25 7 13 21-21-13-7 25-7-25-21 13 13-21L0 40l25-7-13-21 21 13z" fill="currentColor"/></svg>'
logo='<span class="logo-mark" aria-hidden="true"><svg viewBox="0 0 44 46"><path d="M22 20S8 12 12 6c3-5 8-2 10 1 2-3 7-6 10-1 4 6-10 14-10 14z" fill="currentColor"/><path d="M4 29q6-7 12 0t12 0t12 0M4 39q6-7 12 0t12 0t12 0" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/></svg></span><span class="logo-type">living life<br><b>with insulin</b></span>'
def img(id,cls='',sizes='(max-width: 700px) 92vw, 45vw',eager=False):
 p=pm[id];return f'<img class="{cls}" src="/assets/{id}-1000.webp" srcset="/assets/{id}-600.webp 600w, /assets/{id}-1000.webp 1000w, /assets/{id}-1600.webp 1600w" sizes="{sizes}" width="{p["width"]}" height="{p["height"]}" alt="{E(p["alt"])}" style="object-position:{p["focal"]}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""}>'
def cta(label='Your journey starts here',cls='button primary'):
 return f'<a class="{cls}" href="{WA}" target="_blank" rel="noopener noreferrer">{label}{arrow}</a>'
def link(url,label,cls='text-link'):return f'<a class="{cls}" href="{url}">{label}{arrow}</a>'
def photo_button(id,cls='photo-tile',caption=True):
 p=pm[id];return f'<button class="{cls}" type="button" data-photo="{id}" aria-label="Open photo: {E(p["title"])}">{img(id)}{f"<span>{p[chr(116)+chr(105)+chr(116)+chr(108)+chr(101)]}</span>" if caption else ""}<i class="expand" aria-hidden="true">↗</i></button>'
nav=[('','Home'),('our-story','Our story'),('trips','Explore trips'),('community','The community'),('stories','Stories'),('faq','FAQs')]
def header(active):
 links=''.join(f'<a href="/{p+"/" if p else ""}" {"aria-current=page" if p==active else ""}>{label}</a>' for p,label in nav)
 return f'<a class="skip" href="#main">Skip to content</a><header class="header"><div class="header-inner"><a class="brand" href="/" aria-label="Living Life With Insulin home">{logo}</a><nav class="desktop-nav" aria-label="Main navigation">{links}</nav>{cta(cls="button primary header-cta")}<button id="menu-toggle" class="menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-nav"><span></span><span></span></button></div><nav id="mobile-nav" class="mobile-nav" aria-label="Mobile navigation" hidden>{links}{cta()}</nav></header>'
def footer():
 return f'<footer><div class="footer-top wrap"><div class="footer-brand"><a class="brand" href="/">{logo}</a><p>A community built through travel.<br>A little adventure. A lot of belonging.</p></div><div><span class="footer-label">Come along</span><a href="/our-story/">Our story</a><a href="/trips/">Explore trips</a><a href="/community/">The community</a></div><div><span class="footer-label">Stay curious</span><a href="/stories/">Stories & journal</a><a href="/faq/">Your questions, answered</a><a href="/contact/">Get in touch</a></div><div class="footer-hello"><span class="footer-label">It starts with a hello.</span><a href="{WA}" target="_blank" rel="noopener noreferrer">Talk to Anurati ↗</a><span class="phone">{data["phone"]}</span><small>No pressure. Just a conversation.</small></div></div><div class="footer-note wrap">Made for the journeys, the memories, and the people we find along the way.</div><div class="footer-bottom wrap"><span>© 2026 Living Life With Insulin</span><div><a href="/privacy/">Privacy & photos</a><a href="/terms/">Website & booking information</a><button class="motion-toggle" type="button" aria-pressed="false">Pause motion <span aria-hidden="true">Ⅱ</span></button></div></div></footer>'
def closing():return f'<section class="closing wrap reveal"><div class="closing-photo">{img("beach")}</div><div class="closing-copy"><span class="eyebrow">THIS COULD BE THE BEGINNING</span><h2>You came for a trip.<br>You found <em>so much more.</em></h2><p>New places. New friendships. New stories.<br>Perhaps a little more confidence in yourself, too.</p>{cta()}{link("/community/","Meet our community")}</div>{star}</section>'
def page_top(eyebrow,title,copy,extra=''):
 return f'<section class="page-top wrap"><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p>{extra}</section>'
def faq_block(items,cls=''):
 return '<div class="faq-list '+cls+'">'+''.join(f'<details><summary>{E(x["q"])}<span aria-hidden="true">+</span></summary><div class="faq-answer"><p>{E(x["a"])}</p></div></details>' for x in items)+'</div>'
def chapter_card(ch):
 return f'<a class="chapter-card" href="/trips/{ch["slug"]}/" data-category="{ch["category"]}" data-destination="{ch.get("destination") or ""}"><div class="chapter-image">{img(ch["cover"])}<span class="photo-label">From the photo album</span><span class="round-arrow">{arrow}</span></div><span class="eyebrow">{ch["eyebrow"]}</span><h3>{ch["name"]}</h3><p>{ch["description"]}</p></a>'
def empty_horizon(compact=False):
 return f'<div class="horizon {"compact" if compact else ""}"><div class="horizon-sun" aria-hidden="true"><span></span><i></i><i></i><i></i></div><div><span class="eyebrow">OUR NEXT CHAPTER</span><h2>Something wonderful<br>is on the <em>horizon.</em></h2><p>New trips will be shared here once the details are ready. Until then, tell Anurati what you’re hoping to explore.</p>{cta("Let’s talk about your next trip")}</div></div>'
def trip_card(t):
 details=' · '.join(str(t[k]) for k in ['dates','duration','price'] if t.get(k))
 return f'<a class="chapter-card" href="/trips/{E(t["slug"])}/" data-destination="{E(t.get("destination") or "")}" data-month="{E(t.get("month") or "")}" data-experience="{E(t.get("experience") or "")}"><div class="chapter-image">{img(t["cover"])}<span class="photo-label">{E(t.get("status") or "Upcoming")}</span><span class="round-arrow">{arrow}</span></div><span class="eyebrow">{E(t.get("destination") or "")}</span><h3>{E(t["name"])}</h3><p>{E(details)}</p><p>{E(t.get("description") or "")}</p><span class="text-link">Explore this trip {arrow}</span></a>'
def horizon(compact=False):
 trips=data['upcomingTrips']
 if not trips:return empty_horizon(compact)
 filters=''
 if not compact:
  for key,label in [('destination','Destination'),('month','Month'),('experience','Experience')]:
   options=sorted(set(str(t[key]) for t in trips if t.get(key)))
   if options: filters+=f'<label>{label}<select data-trip-filter="{key}"><option value="">All {label.lower()}s</option>'+''.join(f'<option value="{E(o)}">{E(o)}</option>' for o in options)+'</select></label>'
 return f'<div class="confirmed-trips"><div class="trip-filters">{filters}</div><div class="chapters">'+''.join(trip_card(t) for t in trips)+'</div><p class="trip-empty" hidden>No trips match these filters. Try another selection.</p></div>'
def trip_detail(t):
 blocks=''
 for key,label in [('itinerary','The plan'),('included','What’s included'),('excluded','What’s not included'),('accommodation','Where you’ll stay'),('transport','Getting there'),('payment','Costs & payment'),('t1dPlanning','Planning around your needs'),('emergencyArrangements','Support arrangements'),('cancellation','Cancellation & refunds')]:
  content=t.get(key)
  if not content:continue
  formatted='<ul>'+''.join(f'<li>{E(str(item))}</li>' for item in content)+'</ul>' if isinstance(content,list) else '<p>'+E(str(content))+'</p>'
  blocks+=f'<section class="trip-info-block"><h2>{label}</h2>{formatted}</section>'
 details=' · '.join(str(t[k]) for k in ['destination','dates','duration','price'] if t.get(k))
 return page_top('UPCOMING WITH LLWI',E(t['name']),E(t.get('description') or ''),cta())+f'<section class="wrap"><div class="chapter-hero">{img(t["cover"],eager=True)}</div><p class="trip-facts">{E(details)}</p><div class="trip-information">{blocks}<section class="trip-info-block"><h2>Your first trip with us?</h2><p>Ask Anurati about the plans and group arrangements. Confirm any details that matter to you before you book.</p><p>Community support does not replace personal diabetes management or professional medical care.</p>{cta("I’d love to know more about this trip")}</section><section class="trip-info-block"><h2>Your host</h2><p>{E(data['founder']['bio'])}</p></section></div><div class="gallery-grid small-gallery">'+''.join(photo_button(i) for i in t.get('photos',[]))+'</div></section>'+closing()

def steps():
 arr=[('Say hello.','Start with a WhatsApp message to Anurati. Ask anything. No obligation to book.'),('Find your kind of trip.','Get to know the plans, the people behind them, and what to expect.'),('Make it yours.','Confirm the details, plan for your needs, then get ready for new memories.')]
 return '<div class="steps">'+''.join(f'<div><span class="step-number">0{i+1}</span><h3>{h}</h3><p>{p}</p></div>' for i,(h,p) in enumerate(arr))+'</div>'
home_content=json.loads((root/'content/home.json').read_text(encoding='utf-8'))
values=home_content['values']
def value_grid():
 return '<div class="value-grid">'+''.join(f'<article class="value-card {color} reveal"><div class="value-image">{img(id)}</div><div class="value-copy"><span class="small-number">0{i+1}</span><h3>{title}</h3><p>{copy}</p></div></article>' for i,(title,copy,id,color) in enumerate(values))+'</div>'
def home():
 return f'''<section class="hero wrap"><div class="hero-copy"><span class="eyebrow"><i class="tiny-sun"></i> A COMMUNITY BUILT THROUGH TRAVEL</span><h1>Go places.<br>Find your<br><em>people.</em><svg class="underline" viewBox="0 0 360 20" aria-hidden="true"><path d="M5 13Q165-4 350 11M55 18Q160 6 294 16" fill="none" stroke="currentColor" stroke-width="5" stroke-linecap="round"/></svg></h1><p>{E(home_content['heroDescription'])}</p><div class="hero-actions">{cta()}{link('/trips/','Explore our trips')}</div><div class="hero-footnote"><span class="little-heart">♡</span> Come as you are. There’s room for your story.</div></div><div class="hero-collage"><div class="photo-blob" aria-hidden="true"></div><figure class="hero-main">{img('boat',eager=True)}<figcaption>new places, familiar feelings</figcaption></figure><figure class="hero-small">{img('waterfall',eager=True)}<figcaption>a little adventure ↗</figcaption></figure><figure class="hero-wide">{img('beach',eager=True)}<figcaption>better, together.</figcaption></figure><div class="sun-sticker">{star}<span>good places.<br><b>great people.</b></span></div><span class="hand-note">your next chapter?<svg viewBox="0 0 70 45" aria-hidden="true"><path d="M4 5q65-5 45 32m-8-14 9 16 15-10" fill="none" stroke="currentColor" stroke-width="2"/></svg></span></div><a class="scroll-note" href="#come-as-you-are">A little further, a little closer <span>↓</span></a></section>
<div class="ribbon" aria-label="Belonging, adventure, friendship, discovery"><div>New places <span>✳</span> Real connections <span>✳</span> Shared adventures <span>✳</span> A place to belong <span>✳</span> A little more you</div></div>
<section class="intro section wrap reveal" id="come-as-you-are"><span class="eyebrow">MORE THAN THE DESTINATION</span><h2>Come as you are.<br>Find something <em>extraordinary.</em></h2><div class="intro-bottom"><span class="intro-star">{star}</span><p>Maybe you’re here for adventure. Maybe for the people.<br>Maybe you’re simply curious about what happens when you try something new.</p><p>Whatever brings you here,<br><strong>there’s room for your story.</strong></p></div></section>
<section class="values section wrap"><div class="section-head reveal"><div><span class="eyebrow">WHAT YOU MIGHT FIND</span><h2>A trip. And a whole<br>lot of <em>possibility.</em></h2></div><p>Some things won’t fit in your suitcase.<br>They come home with you anyway.</p></div>{value_grid()}</section>
<section class="moments section"><div class="section-head wrap reveal"><div><span class="eyebrow">THE LITTLE MOMENTS</span><h2>Sometimes, being<br><em>understood</em> is everything.</h2></div><div class="moment-intro"><p>The conversations that need no explanation. The laughter between plans. The freedom to just be yourself.</p><div class="rail-controls"><button type="button" class="circle-button" data-scroll="-1" aria-label="Previous photos">←</button><button type="button" class="circle-button" data-scroll="1" aria-label="Next photos">→</button></div></div></div><div class="photo-rail" id="moments-rail">{''.join(photo_button(i,'moment-photo') for i in ['stairs','celebrate','colour','evening','night'])}</div><div class="wrap rail-footer">{link('/community/','A little look into our world')}</div></section>
<section class="section wrap adventure-section"><div class="section-head reveal"><div><span class="eyebrow">WHERE NEXT?</span><h2>Big adventures.<br>Even bigger <em>connections.</em></h2></div>{link('/trips/','Explore the adventures')}</div>{horizon(True)}<div class="mini-heading"><span>POSTCARDS FROM OUR COMMUNITY</span><span>Real people. Real moments.</span></div><div class="chapters">{''.join(chapter_card(ch) for ch in data['photoChapters'])}</div></section>
<section class="reassurance section"><div class="wrap"><div class="section-head reveal"><div><span class="eyebrow">YOUR FIRST TRIP STARTS SMALL</span><h2>A little nervous?<br><em>That’s okay.</em></h2></div><div><p>You don’t have to know anyone. You don’t have to have it all figured out. Sometimes, the first step is simply saying hello.</p>{link('/faq/','Your questions, answered')}</div></div>{steps()}{cta('Say hello to Anurati')}</div></section>
<section class="organiser section wrap reveal"><div class="organiser-photo">{img('dinner')}<span class="photo-caption">The people make the place.</span></div><div class="organiser-copy"><span class="eyebrow">THE PERSON BEHIND THE INVITATION</span><h2>A hello from<br><em>Anurati.</em></h2><span class="role">FOUNDER & HOST, LLWI</span><p>{data['founder']['bio']}</p><p>Have a question, a little hesitation, or a place you’d love to go? She’s your first hello.</p>{link('/our-story/','Get to know LLWI')}</div></section>
<section class="quick-faq section wrap reveal"><div><span class="eyebrow">A FEW THINGS YOU MIGHT BE WONDERING</span><h2>Before you<br>say <em>hello.</em></h2>{link('/faq/','All your questions')}</div>{faq_block(data['faqs'][:2]+[data['faqs'][6],data['faqs'][11]])}</section>{closing()}'''
def story():return page_top('OUR STORY','It was never just<br>about the <em>destination.</em>','Some journeys take you somewhere new. Others bring you closer to people who understand.')+f'<div class="story-banner wrap">{img("beach",eager=True)}<span>A shared journey. A story of your own.</span></div><section class="section wrap story-body reveal"><span class="eyebrow">LIVING LIFE WITH INSULIN</span><div><h2>Built through travel.<br>Held together by <em>people.</em></h2><p>Living Life With Insulin brings people living with Type 1 diabetes together through travel and shared experiences. The destination gives us a reason to meet. The moments along the way give us a chance to connect.</p><p>There is space for the adventure you’ve been dreaming of, the quiet conversation you didn’t know you needed, and simply enjoying somewhere new.</p><p>You might arrive with friends, or not know a soul. You might love exploring, or be wondering whether this is for you. Every person arrives with a different story.</p><h3>There’s no one way to belong.</h3><p>We care about connection, curiosity and being yourself. Everyday T1D routines can be part of the day without having to be the whole story.</p></div></section><section class="founder-section section"><div class="wrap founder-layout"><div class="founder-monogram" aria-label="Anurati, founder and host"><span>A</span>{star}<small>YOUR FIRST HELLO</small></div><div><span class="eyebrow">MEET YOUR HOST</span><h2>Anurati</h2><span class="role">FOUNDER & HOST</span><p>{data["founder"]["bio"]}</p><p>The team is here to talk through the experience, answer questions and help you understand what to expect before you decide to join.</p>{cta()}</div></div></section><section class="section wrap"><div class="section-head"><div><span class="eyebrow">THE FEELING WE’RE HERE FOR</span><h2>A little more<br><em>possibility.</em></h2></div><p>A sense of accomplishment. A shared memory.<br>A connection that feels like the beginning.</p></div>{value_grid()}</section>{closing()}'
def trips():
 return page_top('EXPLORE WITH LLWI','Big adventures.<br>Even bigger <em>connections.</em>','Find an experience that feels like you. Then see what happens when you share it.')+f'<section class="trip-browser wrap section"><div class="filter-top"><div class="tab-buttons" role="group" aria-label="Trip collection"><button type="button" data-trip-tab="upcoming" class="active" aria-pressed="true">On the horizon</button><button type="button" data-trip-tab="past" aria-pressed="false">Past adventures</button></div><span class="collection-note">A new chapter is worth waiting for.</span></div><div id="upcoming-panel">{horizon()}<p class="honest-note">Confirmed dates, prices and arrangements will appear with each announced trip.</p></div><div id="past-panel" hidden><div class="album-intro"><h2>Little postcards.<br><em>Lasting feelings.</em></h2><p>A look back through our community photo album. These are collections of past moments, not current trip listings.</p></div><div class="chips" role="group" aria-label="Filter past adventures"><button type="button" data-chapter-filter="all" class="active" aria-pressed="true">All moments</button><button type="button" data-chapter-filter="water" aria-pressed="false">By the water</button><button type="button" data-chapter-filter="outdoors" aria-pressed="false">Outdoors</button><button type="button" data-chapter-filter="together" aria-pressed="false">Together</button></div><div class="chapters">{"".join(chapter_card(ch) for ch in data["photoChapters"])}</div><p id="chapter-count" class="filter-count" aria-live="polite">3 photo collections</p></div></section><section class="reassurance section"><div class="wrap"><span class="eyebrow">BEFORE YOU PACK YOUR BAGS</span><h2>Let’s find what<br>feels <em>right for you.</em></h2>{steps()}{link("/faq/","Read the first-timer FAQs")}</div></section>{closing()}'
def chapter(ch):
 return f'<div class="wrap breadcrumb"><a href="/trips/#past">Past adventures</a><span>/</span>{ch["name"]}</div>'+page_top('FROM THE LLWI PHOTO ALBUM',ch['name']+'.',ch['description'])+f'<section class="wrap chapter-detail"><div class="chapter-hero">{img(ch["cover"],eager=True)}</div><div class="chapter-summary"><div><span class="eyebrow">A COLLECTION OF PAST MOMENTS</span><h2>Places are lovely.<br>The company makes it <em>special.</em></h2></div><div><p>These photographs are a glimpse into the LLWI community. This album is not an upcoming departure or a bookable itinerary.</p><p>Looking for a similar experience? Ask Anurati what’s coming next, including dates, costs, activities, accommodation and T1D-related planning.</p>{cta("I’d love to know more")}</div></div><div class="gallery-grid small-gallery">{"".join(photo_button(i) for i in ch["photos"])}</div></section><section class="section wrap quick-faq"><div><span class="eyebrow">FOR YOUR NEXT ADVENTURE</span><h2>A few practical<br><em>questions.</em></h2></div>{faq_block([data["faqs"][6],data["faqs"][10],data["faqs"][12]])}</section>{closing()}'
def community():return page_top('THE COMMUNITY','Different stories.<br>One beautiful <em>connection.</em>','You don’t have to know anyone to belong. Start with a hello, and a little curiosity about where it might lead.',cta())+f'<section class="community-feature wrap"><div>{img("stairs",eager=True)}</div><div class="community-note"><span class="eyebrow">THE IN-BETWEEN MOMENTS</span><h2>Some journeys<br>bring you <em>home.</em></h2><p>Not to a place, but to people who understand.</p><p>The laughter between plans. The conversations that don’t need a long explanation. The comfort of showing up as yourself.</p>{star}</div><div>{img("celebrate",eager=True)}</div></section><section class="section wrap"><div class="section-head"><div><span class="eyebrow">OUR SHARED PHOTO ALBUM</span><h2>A little look<br>into our <em>world.</em></h2></div><p>Real moments from the LLWI community.<br>Tap a photograph to stay a little longer.</p></div><div class="chips" role="group" aria-label="Filter photos"><button class="active" data-gallery-filter="all" aria-pressed="true">All the moments</button><button data-gallery-filter="water" aria-pressed="false">By the water</button><button data-gallery-filter="outdoors" aria-pressed="false">Outdoors</button><button data-gallery-filter="together" aria-pressed="false">Together</button></div><div class="gallery-grid" id="community-gallery">{"".join(f"<div data-category=\"{p['category']}\">{photo_button(p['id'])}</div>" for p in photos)}</div><p id="gallery-count" class="filter-count" aria-live="polite">13 moments to explore</p></section><section class="story-invite section wrap"><span class="eyebrow">IN YOUR OWN WORDS</span><h2>We came as strangers.<br>We left with <em>stories.</em></h2><p>Traveller stories will have a home here, shared in their own words and with their permission. Have a memory you’d like to contribute?</p>{cta("Share a moment with Anurati")}</section>{closing()}'
articles=json.loads((root/'content/journal.json').read_text(encoding='utf-8'))

def story_card(a):return f'<a class="journal-card" href="/stories/{a["slug"]}/"><div>{img(a["photo"])}</div><span class="eyebrow">{a["category"]}</span><h3>{a["title"]}</h3><p>{a["intro"]}</p><span class="text-link">Read the reflection {arrow}</span></a>'
def stories():return page_top('THE LLWI JOURNAL','A few words for<br>the <em>journey.</em>','Thoughts on first steps, new connections and what we take home. A place for curiosity, before and after the trip.')+f'<section class="section wrap journal-grid">{"".join(story_card(a) for a in articles)}</section><section class="story-invite section wrap"><span class="eyebrow">YOUR VOICE BELONGS HERE</span><h2>Every journey<br>has a <em>story.</em></h2><p>These journal reflections are invitations to think about travel and connection. Personal traveller stories will be added with their contributors’ permission.</p>{cta("Tell us your story")}</section>{closing()}'
def article(a):return f'<div class="breadcrumb wrap"><a href="/stories/">Journal</a><span>/</span>{a["category"]}</div>'+page_top(a['category'].upper(),a['title'],a['intro'])+f'<article class="journal-article"><div class="article-cover">{img(a["photo"],eager=True)}</div><div class="article-body"><span class="eyebrow">A JOURNAL REFLECTION · 2 MIN READ</span>{"".join(f"<h2>{E(h)}</h2><p>{E(p)}</p>" for h,p in a["body"])}<div class="article-end">{cta()}{link("/stories/","Back to the journal")}</div></div></article>'
def faq():return page_top('A LITTLE REASSURANCE','Good questions.<br>Honest <em>answers.</em>','The big things, the small things, and the things you might feel shy about asking. You can always talk to Anurati.')+f'<section class="section wrap faq-layout"><aside><span class="eyebrow">FIND YOUR ANSWER</span><a href="#your-first-trip">Your first trip</a><a href="#the-experience">The experience</a><a href="#planning-practicalities">Planning & practicalities</a><a href="#booking-enquiries">Booking & enquiries</a><div class="faq-aside-card"><h3>Still wondering?</h3><p>You don’t need the perfect question to say hello.</p>{cta("Talk to Anurati")}</div></aside><div>'+''.join(f'<section class="faq-group" id="{anchor}"><h2>{group}</h2>{faq_block([f for f in data["faqs"] if f["group"]==group])}</section>' for group,anchor in [('Your first trip','your-first-trip'),('The experience','the-experience'),('Planning & practicalities','planning-practicalities'),('Booking & enquiries','booking-enquiries')])+f'</div></section><div class="wrap faq-bottom">{cta()}</div>'
def contact():return f'<section class="contact-page wrap"><div><span class="eyebrow">NO BIG LEAP REQUIRED</span><h1>It starts<br>with a <em>hello.</em></h1><p>A question about a trip. A little curiosity about the community. A place you’d love to explore. Anurati would love to hear from you.</p><div class="message-preview"><span class="eyebrow">YOUR FIRST MESSAGE</span><p>I would like to know more.</p><span>You can edit it in WhatsApp before you send.</span></div>{cta()}<div class="contact-person"><strong>Anurati</strong><span>Founder & host · {data["phone"]}</span></div><p class="small-copy">No forms. No obligation to book.<br>Just a conversation about what could come next.</p></div><div class="contact-photo">{img("boat",eager=True)}<span class="contact-sticker">Your next favourite<br><em>memory?</em></span></div></section>'
def privacy():return page_top('PRIVACY & PHOTOGRAPHS','A little care<br>goes a <em>long way.</em>','Information about this website, your enquiry and the photographs you see here.')+f'<article class="legal-body wrap"><h2>Browsing this website</h2><p>This website has no enquiry form, payment checkout or health-information form. It does not include custom advertising trackers or analytics. The hosting provider may process technical information needed to deliver and protect the site.</p><h2>Starting a conversation</h2><p>Contact buttons open WhatsApp with a short, prefilled message. Nothing is sent automatically. You decide whether to edit and send the message. WhatsApp handles that conversation under its own terms and privacy practices. Share only the information you want to discuss.</p><h2>Photos and personal stories</h2><p>The photographs on this site are from the LLWI community album. Captions describe the scene without identifying anyone’s health status. If you have a question about a photograph, its use, or a correction or removal request, contact Anurati.</p><h2>Motion preference</h2><p>The motion control changes the animation for your current visit. The site also respects your device’s reduced-motion setting. It does not save this preference to a tracking profile.</p><h2>Trip and booking information</h2><p>Before sharing personal details or booking, ask Anurati how booking information will be used, stored and shared. Trip-specific arrangements should be confirmed directly.</p>{cta("Contact Anurati")}</article>'
def terms():return page_top('WEBSITE & BOOKING INFORMATION','Clear details.<br>A confident <em>first step.</em>','A few things to know before you enquire or plan a trip.')+f'<article class="legal-body wrap"><h2>About the website</h2><p>This is an introduction to Living Life With Insulin and its community. Photo albums show past moments; they are not offers to book a departure. Journal reflections are general editorial content, not traveller testimonials.</p><h2>Before you book</h2><p>Confirm the itinerary, dates, group size, price, inclusions, exclusions, accommodation, transport, payment terms and eligibility with Anurati. Request the trip’s written cancellation, refund and transfer policies before making any payment. This website does not process bookings or payments.</p><h2>Individual needs and support</h2><p>Support arrangements, accessibility, meals, emergency plans and any insurance or medical personnel must be confirmed for the specific trip. Community and group planning do not replace individual diabetes management or professional medical care. This website does not provide medical advice.</p><h2>Questions or corrections</h2><p>If something is unclear, or you spot information that needs correcting, please get in touch with Anurati.</p>{cta("Ask Anurati")}</article>'
pages={}
def write_page(path,title,desc,body,active=''):
 rel=path.strip('/'); f=dist/rel/'index.html' if rel else dist/'index.html';f.parent.mkdir(parents=True,exist_ok=True)
 url=origin+('/'+rel+'/' if rel else '/')
 content=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#2458df"><title>{E(title)} | Living Life With Insulin</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)} | LLWI"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{origin}/assets/beach-1600.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/jakarta.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body data-page="{active}"><canvas id="fluid-bg" aria-hidden="true"></canvas>{header(active)}<main id="main">{body}</main>{footer()}<dialog id="lightbox" aria-labelledby="lightbox-caption"><div class="lightbox-top"><span id="lightbox-count"></span><button type="button" class="lightbox-close" aria-label="Close photo viewer">Close ×</button></div><div class="lightbox-image-wrap"><button class="lightbox-prev" type="button" aria-label="Previous photo">←</button><img id="lightbox-img" alt=""><button class="lightbox-next" type="button" aria-label="Next photo">→</button></div><p id="lightbox-caption"></p></dialog></body></html>'''
 f.write_text(relative_urls(content, rel), encoding='utf-8');pages[url]=title
write_page('','Go places. Find your people.','Travel, connection and shared adventures with the Living Life With Insulin community.',home())
for path,title,fn,active in [('our-story','Our story',story,'our-story'),('trips','Explore trips',trips,'trips'),('community','The community',community,'community'),('stories','Stories & journal',stories,'stories'),('faq','Your questions, answered',faq,'faq'),('contact','Say hello to Anurati',contact,'contact'),('privacy','Privacy & photographs',privacy,'privacy'),('terms','Website & booking information',terms,'terms')]:write_page(path,title,'Living Life With Insulin. A community built through travel, shared experiences and connection.',fn(),active)
for t in data['upcomingTrips']:write_page('trips/'+t['slug'],t['name'],t.get('description') or '',trip_detail(t),'trips')
for ch in data['photoChapters']:write_page('trips/'+ch['slug'],ch['name']+' · Photo album',ch['description'],chapter(ch),'trips')
for a in articles:write_page('stories/'+a['slug'],a['title'],a['intro'],article(a),'stories')
(dist/'assets/photos.json').write_text(json.dumps(photos))
if origin:
 (dist/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{E(url)}</loc></url>' for url in pages)+'</urlset>', encoding='utf-8')
else:
 (dist/'sitemap.xml').unlink(missing_ok=True)
(dist/'robots.txt').write_text('User-agent: *\nAllow: /\n' + ('Sitemap: '+origin+'/sitemap.xml\n' if origin else ''), encoding='utf-8')
(dist/'.nojekyll').touch()
(dist/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="20" fill="#2458df"/><path d="M32 35S10 23 17 14c5-6 12-2 15 3 3-5 10-9 15-3 7 9-15 21-15 21z" fill="#ffb9d2"/><path d="M12 46q7-8 14 0t14 0t14 0" stroke="white" stroke-width="3" fill="none" stroke-linecap="round"/></svg>')



print(f'Built {len(pages)} pages in docs/.')
